import unittest
from stats import mean, spread

class TestStats(unittest.TestCase):
    def test_mean(self):
        self.assertEqual(mean([2, 4, 6]), 4)

    def test_spread(self):
        self.assertEqual(spread([2, 4, 6]), 4)

